// Helper to create valid MCQ
function createQ(track, idNum, topic, difficulty, question, options, correctIndex, explanation, tags = []) {
  if (options.length !== 4) throw new Error(`Question ${track}-${idNum} must have exactly 4 options`);
  if (correctIndex < 0 || correctIndex > 3) throw new Error(`Invalid correctIndex for ${track}-${idNum}`);
  return {
    id: `Q-${track.toUpperCase()}-${String(idNum).padStart(3, '0')}`,
    track,
    topic,
    difficulty,
    type: 'MCQ',
    question,
    options,
    correctIndex,
    explanation,
    tags,
    isSample: true,
  };
}

